use ImAuthenticator\Security;use ImAuthenticator\Web;
$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$id=(int)($_GET['id']??$_POST['application_id']??0);$app=$db->one('SELECT * FROM applications WHERE id=? AND deleted_at IS NULL',[$id]);if(!$app){http_response_code(404);exit;}if(!$appAdmins->canManage((int)$user['id'],$id,'security')){http_response_code(403);exit('Brak uprawnień.');}$msg='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$entity=trim((string)$_POST['entity_id']);$acs=trim((string)$_POST['acs_url']);$slo=trim((string)($_POST['slo_url']??''));$nameid=trim((string)($_POST['name_id_format']??'urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress'));if($entity===''||strlen($entity)>2048)throw new RuntimeException('Entity ID jest wymagane.');if(!Security::validRedirectUri($acs))throw new RuntimeException('ACS URL musi być dokładnym adresem HTTPS.');if($slo!==''&&!Security::validRedirectUri($slo))throw new RuntimeException('SLO URL musi być dokładnym adresem HTTPS.');$db->execute('INSERT INTO application_saml_settings(application_id,entity_id,acs_url,slo_url,name_id_format,sign_assertions,encrypt_assertions) VALUES(?,?,?,?,?,1,0) ON DUPLICATE KEY UPDATE entity_id=VALUES(entity_id),acs_url=VALUES(acs_url),slo_url=VALUES(slo_url),name_id_format=VALUES(name_id_format),sign_assertions=1,encrypt_assertions=0',[$id,$entity,$acs,$slo?:null,$nameid?:null]);$audit->write('application.saml.updated','success',(int)$user['id'],null,$id,null,['entity_id'=>$entity,'acs_url'=>$acs]);$msg='<div class="alert success">Konfiguracja SAML została zapisana.</div>';}catch(Throwable $e){$msg='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}$s=$db->one('SELECT * FROM application_saml_settings WHERE application_id=?',[$id])??[];$metadata=rtrim((string)$config['issuer'],'/').'/saml/metadata';$sso=rtrim((string)$config['issuer'],'/').'/saml/sso';$sloIdp=rtrim((string)$config['issuer'],'/').'/saml/slo';$content='<div class="page-head"><div><h1>SAML 2.0 — '.Web::e($app['name']).'</h1><p>imAuthenticator działa jako Identity Provider dla tej aplikacji.</p></div><a class="button" href="/admin/applications/'.$id.'">Aplikacja</a></div>'.$msg.'<section class="card"><h2>Endpointy IdP</h2><div class="code">Metadata: '.Web::e($metadata).'<br>SSO: '.Web::e($sso).'<br>SLO: '.Web::e($sloIdp).'<br>Entity ID: '.Web::e(rtrim((string)$config['issuer'],'/').'/saml').'</div></section><form class="card" method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="application_id" value="'.$id.'"><label>SP Entity ID<input name="entity_id" value="'.Web::e($s['entity_id']??'').'" required></label><label>Assertion Consumer Service URL<input type="url" name="acs_url" value="'.Web::e($s['acs_url']??'').'" required></label><label>SP Single Logout URL<input type="url" name="slo_url" value="'.Web::e($s['slo_url']??'').'"></label><label>NameID Format<input name="name_id_format" value="'.Web::e($s['name_id_format']??'urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress').'"></label><div class="alert warning">Assertion jest zawsze podpisana RSA-SHA256. Dostęp użytkownika do aplikacji jest sprawdzany przed utworzeniem assertion.</div><button class="primary">Zapisz SAML</button></form>';Web::page('SAML 2.0',$content,$user);
